// MingCute icon names are snake_case by design — keep them 1:1 with the icon set.
// ignore_for_file: constant_identifier_names

/// App icon set — MingCute everywhere except the CityBee brand marks.
/// Nav tabs, detail actions and category visuals all render through the
/// iconify bundle; swapping a look means editing only this file.
abstract final class AppIcons {
  // ── Bottom navigation (line = inactive, fill = active) ─────────────
  static const home = AppUiIcons.homeFill;
  static const homeOutline = AppUiIcons.homeLine;
  static const offers = AppUiIcons.offersFill;
  static const offersOutline = AppUiIcons.offersLine;
  static const services = AppUiIcons.servicesFill;
  static const servicesOutline = AppUiIcons.servicesLine;
  static const explore = AppUiIcons.exploreFill;
  static const exploreOutline = AppUiIcons.exploreLine;
  static const business = AppUiIcons.storeFill;
  static const businessOutline = AppUiIcons.storeLine;
  static const more = AppUiIcons.moreFill;
  static const moreOutline = AppUiIcons.moreLine;

  // ── Detail-page actions ────────────────────────────────────────────
  static const callAsset = AppUiIcons.phoneFill;
  static const whatsappAsset = AppUiIcons.whatsappFill;
  static const directionsAsset = AppUiIcons.directionsFill;

  /// Nav icon: colored by the caller (orange active / slate inactive).
  static Widget nav(String iconData, {double size = 23, Color? color, Key? key}) =>
      Iconify(iconData, size: size, color: color, key: key);

  /// Renders one of the action icons at [size].
  static Widget action(String iconData, {double size = 20, Color? color}) =>
      Iconify(iconData, size: size, color: color);
}

